import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth, requestHeaderPUTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "ViewProgram.js";

class ViewProgram extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            program: null,
            error: null,
            isEditing: false,
            editName: '',
            editDescription: '',
            editType: 'WORK',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
            subPrograms: [],
            subProgramsLoading: false,
            subProgramsError: null,
        };
    }

    componentDidMount() {
        document.title = "View Program";
        this.fetchProgram();
        this.fetchSubPrograms();
    }

    fetchProgram() {
        const programId = this.props.match.params.programId;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/' + programId;

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchProgram", "SUCCESS", "result", result);
            this.setState({ isLoaded: true, program: result.data });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchProgram", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    fetchSubPrograms() {
        const programId = this.props.match.params.programId;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list';
        const payload = JSON.stringify({ page: 1, size: 100, search: '', programId: Number(programId) });

        this.setState({ subProgramsLoading: true });

        fetch(API_URL, requestHeaderPOSTWithAuth(payload, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchSubPrograms", "SUCCESS", "result", result);
            this.setState({ subProgramsLoading: false, subPrograms: result.data?.content || result.data || [] });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchSubPrograms", "ERROR", "error", error);
            this.setState({ subProgramsLoading: false, subProgramsError: error.message });
        });
    }

    startEditing = () => {
        const { program } = this.state;
        this.setState({ isEditing: true, editName: program.name, editDescription: program.description || '', editType: program.type });
    }

    cancelEditing = () => {
        this.setState({ isEditing: false });
    }

    saveChanges = () => {
        const { program, editName, editDescription, editType } = this.state;
        const payload = { name: editName, description: editDescription || null, type: editType };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/' + program.id;

        fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "saveChanges", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1, program: result.data, isEditing: false });
            setTimeout(() => this.setState({ loadingModalVisible: false, loadingModalState: 0 }), 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "saveChanges", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    render() {
        const { isLoaded, program, error, isEditing } = this.state;

        if (!isLoaded) return <Loading />;

        if (error) {
            return (
                <div style={{ textAlign: 'center', padding: '40px', color: '#dc3545' }}>
                    <h3>Error loading program</h3>
                    <p>{error}</p>
                    <a href="#/programs">← Back</a>
                </div>
            );
        }

        return (
            <div>
                <a href="#/programs" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Programs List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <CCard className="p-4">
                                <CCardBody>
                                    {!isEditing ? this.renderViewMode() : this.renderEditMode()}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderViewMode() {
        const { program } = this.state;

        return (
            <>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h1>🏗️ {program.name}</h1>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="secondary" onClick={() => { this.fetchProgram(); this.fetchSubPrograms(); }} title="Refresh">🔄</CButton>
                        <CButton color="primary" onClick={this.startEditing}>✏️ Edit</CButton>
                    </div>
                </div>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <h5>📝 Description</h5>
                    <p>{program.description || 'No description'}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>Type</h5>
                    <span style={{
                        padding: '4px 12px',
                        borderRadius: '4px',
                        backgroundColor: program.type === 'WORK' ? '#e3f2fd' : '#fce4ec',
                        color: program.type === 'WORK' ? '#1565c0' : '#c62828',
                        fontWeight: 'bold',
                    }}>
                        {program.type}
                    </span>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🕐 Created</h5>
                    <p>{program.createdOn ? new Date(program.createdOn).toLocaleString() : '—'}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🔄 Last Updated</h5>
                    <p>{program.updatedOn ? new Date(program.updatedOn).toLocaleString() : '—'}</p>
                </div>
                <hr />
                {this.renderSubPrograms()}
            </>
        );
    }

    renderSubPrograms() {
        const { subPrograms, subProgramsLoading, subProgramsError } = this.state;

        return (
            <div style={{ marginBottom: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h5>📂 Sub-Programs</h5>
                    <a href="#/sub-program/create" target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none' }}>
                        <CButton color="success" size="sm">➕ New Sub-Program</CButton>
                    </a>
                </div>
                {subProgramsLoading && <p>Loading sub-programs...</p>}
                {subProgramsError && <p style={{ color: '#dc3545' }}>Error: {subProgramsError}</p>}
                {!subProgramsLoading && !subProgramsError && subPrograms.length === 0 && (
                    <p style={{ color: '#6c757d', fontStyle: 'italic' }}>No sub-programs found.</p>
                )}
                {!subProgramsLoading && subPrograms.length > 0 && (
                    <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                        <thead>
                            <tr style={{ borderBottom: '2px solid #dee2e6', textAlign: 'left' }}>
                                <th style={{ padding: '8px' }}>#</th>
                                <th style={{ padding: '8px' }}>Name</th>
                                <th style={{ padding: '8px' }}>Description</th>
                            </tr>
                        </thead>
                        <tbody>
                            {subPrograms.map((sp, index) => (
                                <tr key={sp.id} style={{ borderBottom: '1px solid #dee2e6' }}>
                                    <td style={{ padding: '8px' }}>{index + 1}</td>
                                    <td style={{ padding: '8px' }}>
                                        <a href={'#/sub-program/' + sp.id} target="_blank" rel="noopener noreferrer">
                                            {sp.name}
                                        </a>
                                    </td>
                                    <td style={{ padding: '8px', color: sp.description ? 'inherit' : '#6c757d' }}>
                                        {sp.description || '—'}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
        );
    }

    renderEditMode() {
        const { editName, editDescription, editType } = this.state;

        return (
            <>
                <h2>✏️ Edit Program</h2>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Name *</strong></label>
                    <CInput
                        value={editName}
                        onChange={(e) => this.setState({ editName: e.target.value })}
                        required
                    />
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Description</strong></label>
                    <textarea
                        value={editDescription}
                        placeholder="Description (optional)"
                        onChange={(e) => this.setState({ editDescription: e.target.value })}
                        rows="3"
                        style={{ display: 'block', width: '100%', padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px', resize: 'vertical' }}
                    />
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Type *</strong></label>
                    <select
                        value={editType}
                        onChange={(e) => this.setState({ editType: e.target.value })}
                        style={{ display: 'block', width: '100%', padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px' }}
                    >
                        <option value="WORK">WORK</option>
                        <option value="PERSONAL">PERSONAL</option>
                    </select>
                </div>
                <hr />
                <div style={{ display: 'flex', gap: '12px' }}>
                    <CButton color="success" onClick={this.saveChanges}>💾 Save</CButton>
                    <CButton color="secondary" onClick={this.cancelEditing}>Cancel</CButton>
                </div>
            </>
        );
    }
}

export default ViewProgram;
